const ICONS = {"normal":{"180":"","192":"","512":""},"new-year":{"180":"","192":"","512":""},"valentine":{"180":"","192":"","512":""},"st-patrick":{"180":"","192":"","512":""},"easter":{"180":"","192":"","512":""},"independence":{"180":"","192":"","512":""},"halloween":{"180":"","192":"","512":""},"thanksgiving":{"180":"","192":"","512":""},"christmas":{"180":"","192":"","512":""}};
export default function handler(req,res){
  if(req.method!=='GET' && req.method!=='HEAD')return res.status(405).json({error:'Method not allowed'});
  const season=Object.prototype.hasOwnProperty.call(ICONS,req.query.season)?req.query.season:'normal';
  const iconPath=size=>'/api/seasonal-icon?season='+encodeURIComponent(season)+'&size='+size;
  if(req.query.manifest==='1'){
    res.setHeader('Content-Type','application/manifest+json');res.setHeader('Cache-Control','public, max-age=3600');
    return res.status(200).send(JSON.stringify({name:'Good Habits - Beaty Coach',short_name:'Good Habits',description:'Habit, Nutrition, Workout & Finance Tracker with Beaty Coach',id:'/',start_url:'/',display:'standalone',background_color:'#f8fafc',theme_color:'#4f46e5',orientation:'portrait-primary',icons:[192,512].map(size=>({src:iconPath(size),sizes:size+'x'+size,type:'image/png',purpose:'any maskable'}))}));
  }
  const size=['180','192','512'].includes(req.query.size)?req.query.size:'512';
  const buffer=Buffer.from(ICONS[season][size],'base64');res.setHeader('Content-Type','image/png');res.setHeader('Cache-Control','public, max-age=86400');return res.status(200).send(buffer);
}
